const m=document.querySelector('#menu-toggle'),n=document.querySelector('#main-nav');function closeMenu(){m.setAttribute('aria-expanded','false');n.classList.remove('is-open')}m.addEventListener('click',()=>{const open=m.getAttribute('aria-expanded')!=='true';m.setAttribute('aria-expanded',String(open));n.classList.toggle('is-open',open)});n.addEventListener('click',closeMenu);document.addEventListener('click',e=>{if(!e.target.closest('header'))closeMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();m.focus()}});matchMedia('(max-width:650px)').addEventListener('change',closeMenu);